import{_ as e,o as a,c as s,a5 as i}from"./chunks/framework.DrDMl0tG.js";const o="/assets/anymals.DrWO0fZa.png",r="/assets/articulatedSystem.BpH-QZwV.png",u=JSON.parse('{"title":"Articulated Systems","description":"","frontmatter":{},"headers":[],"relativePath":"sections/ArticulatedSystem.md","filePath":"sections/ArticulatedSystem.md"}'),l={name:"sections/ArticulatedSystem.md"};function n(c,t,m,d,h,p){return a(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="articulated-systems" tabindex="-1">Articulated Systems <a class="header-anchor" href="#articulated-systems" aria-label="Permalink to &quot;Articulated Systems&quot;">​</a></h1><img src="'+o+'" alt="" style="width:543px;height:423px;"><p>ANYmal robots (B and C versions) simulated in RaiSim.</p><p><a id="introduction"></a></p><p>An articulated system comprises multiple bodies interconnected via joints. There are two kinds of articulated systems: kinematic trees and closed-loop systems. A kinematic tree has no loops, so each body has exactly one parent joint. Consequently, the number of joints in a kinematic tree equals the number of bodies; the root body of a floating-base system is attached to the world by a floating joint.</p><p>A closed-loop system has one or more loops, i.e., there are multiple paths from a body to the root. RaiSim&#39;s algorithmic backbone, the Articulated Body Algorithm, cannot solve the dynamics of a closed-loop system directly. Instead, RaiSim simulates a spanning tree of the system and closes the loops with pin or equality constraints, which it eliminates exactly before the contact solve. These pages focus on kinematic trees. Closed-loop systems are described in <a href="./articulated_system/ClosedLoopSystems.html">Closed-Loop Systems</a>.</p><p>In kinematic trees, <strong>since each body has only one parent joint, the index of a body always matches that of its parent joint</strong>. Here, a &quot;body&quot; denotes a rigid body composed of one or more &quot;links&quot; that are rigidly connected to each other via fixed joints.</p><ul><li><a href="./articulated_system/Creation.html">Creating an Articulated System</a></li><li><a href="./articulated_system/StateAndKinematics.html">State and Kinematics</a></li><li><a href="./articulated_system/DynamicsAndControl.html">Dynamics and Control</a></li><li><a href="./articulated_system/JointDampingAndFriction.html">Joint Damping and Friction</a></li><li><a href="./Actuators.html">Actuators</a></li><li><a href="./Sensors.html">Sensors</a></li><li><a href="./articulated_system/ModifyingTheModel.html">Modifying the Model in Code</a></li><li><a href="./articulated_system/ClosedLoopSystems.html">Closed-Loop Systems</a></li><li><a href="./articulated_system/MimicJoints.html">Mimic Joints</a></li><li><a href="./articulated_system/Tracks.html">Tracks</a></li><li><a href="./articulated_system/API.html">ArticulatedSystem API</a></li></ul><p><strong>TL;DR</strong></p><p><img src="'+r+'" alt=""></p><p>A vector-graphics version is available as <a href="https://github.com/raisimTech/raisim2Lib/blob/main/rsc/docs/image/articulatedSystem.pdf" target="_blank" rel="noreferrer">articulatedSystem.pdf</a>.</p>',11)])])}const f=e(l,[["render",n]]);export{u as __pageData,f as default};
